// spec: .qa/e2e/specs/home.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { startNearestPrayer } from '../_helpers/prayer-start';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('Главная', () => {
  test('HM-01 Главная: приветствие с именем, дата, ближайшая молитва, счётчики, навигация из 5 табов #6a86f7ea @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. Открыть `/home`.
    await page.goto('/home');
    const start = page.getByRole('button', { name: 'התחל תפילה' });
    await expect(start).toBeVisible({ timeout: 20_000 });

    // 2. Проверить шапку, карточку молитвы, счётчики, секции, нижнюю навигацию.
    await expect(page.getByRole('button', { name: 'מעבר לפרטים שלי' })).toContainText('אקדא טסט');
    await expect(page.getByText(/טוב(ים)? אקדא טסט/)).toBeVisible();
    await expect(page.getByText(/תשפ״ז/).first()).toBeVisible();
    await expect(page.getByRole('button', { name: 'זמני התפילות של היום' })).toContainText(/\d{2}:\d{2} - \d{2}:\d{2}/);
    await expect(page.getByText(/^נוסח /).first()).toBeVisible();
    await expect(page.getByRole('region', { name: /^ימים רצופים: \d+$/ })).toBeVisible();
    await expect(page.getByRole('region', { name: /^תפילות היום: \d+$/ })).toBeVisible();
    await expect(page.getByRole('region', { name: /^סה״כ תפילות: \d+$/ })).toBeVisible();
    await expect(page.getByText('תזכורות מהירות', { exact: true })).toBeVisible();
    await expect(page.getByText('תאריכים חשובים', { exact: true })).toBeVisible();
    const tabs = page.getByRole('tab');
    await expect(tabs).toHaveText(['תהילים', 'תפילות', 'בית', 'המסע שלי', 'ברכות']);
    await expect(page.getByRole('tab', { name: 'בית' })).toHaveAttribute('aria-selected', 'true');

    // 3. Нажать «התחל תפילה»; вернуться на `/home`.
    // Вне окна молитвы кнопка неактивна (норма, решение 2026-10-04): хелпер проверяет disabled + «מתחילה ב-…»
    // и открывает ту же молитву напрямую — проверки страницы молитвы ниже не меняются.
    await startNearestPrayer(page);
    await expect(page).toHaveURL(/\/prayer\/[a-z]+_ashkenaz$/);
    await expect(page.getByRole('heading', { level: 1, name: /\(אשכנזי\)/ })).toBeVisible();
    await page.getByRole('button', { name: 'חזרה' }).click();
    await expect(page).toHaveURL(/\/home$/);

    // 4. По очереди нажать каждый таб нижней навигации.
    const nav: Array<[string, RegExp]> = [
      ['תהילים', /\/tehilim$/],
      ['תפילות', /\/prayers$/],
      ['בית', /\/home$/],
      ['המסע שלי', /\/journey$/],
      ['ברכות', /\/blessings$/],
    ];
    for (const [name, url] of nav) {
      await page.getByRole('tab', { name }).click();
      await expect(page).toHaveURL(url);
    }
  });
});
